excels.excel:

EXPORT WITH SHEET="年度库存盘点差异表", HEADER=true,
    MAPPING={"a":"物料编码","b":"物料名称","c":"账面数量","d":"实盘数量","e":"差异数量","f":"差异率","g":"盘点结果"},
    FORMAT={"c":"#,##0","d":"#,##0","e":"#,##0","f":"0.00%"},
    FORMULAS={
        E2:'D2-C2',F2:'E2/C2',E3:'D3-C3',F3:'E3/C3',E4:'D4-C4',F4:'E4/C4',
        E5:'D5-C5',F5:'E5/C5',E6:'D6-C6',F6:'E6/C6',E7:'D7-C7',F7:'E7/C7',
        C8:'SUM(C2:C7)',D8:'SUM(D2:D7)',E8:'D8-C8',F8:'E8/C8'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E4:{color:red,bold:true}
    }
